export function parseSoarUri(text: string): SoarParseResult | null {
  try {
    // soar://<profile-id>@<server-ip>:<port>?zone=<zone>&pubkey=<base64pubkey>
    const u = new URL(text);
    if (u.protocol !== 'soar:') return null;

    const profileId = decodeURIComponent(u.username);
    if (!profileId) return null;

    const host = u.hostname;
    const port = u.port ?? 53;

    // Parse query parameters for zone and pubkey
    const zone = u.searchParams.get('zone');
    const pubkey = u.searchParams.get('pubkey');

    if (!zone || !pubkey) return null;

    return {
      profileId,
      server: host,
      zone,
      pubkey,
    };
  } catch {
    return null;
  }
}
