const BASE = 'https://netpulse-cloud.shuridehradin.workers.dev';
const API = `${BASE}/api/v1`;
const INBOX = '/api/internal/netpulse/v1';
const email = `smoke-${Date.now()}-${Math.random().toString(16).slice(2, 8)}@example.invalid`;
const password = 'SmokePass!2026x';
const results = [];
const check = (name, ok, detail) => {
  results.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${JSON.stringify(detail).slice(0, 180)}` : ''}`);
};

async function call(path, init = {}) {
  const res = await fetch(`${path.startsWith('http') ? path : `${API}${path}`}`, {
    ...init,
    headers: { 'content-type': 'application/json', ...(init.headers ?? {}) },
    signal: AbortSignal.timeout(25_000),
  });
  const text = await res.text();
  let body = null;
  try { body = text ? JSON.parse(text) : null; } catch { body = text.slice(0, 200); }
  return { status: res.status, body };
}

// ---- health
const health = await call('/health');
check('health 200 ok', health.status === 200 && health.body?.ok === true, { status: health.status, ok: health.body?.ok });

// ---- live login
const reg = await call('/auth/register', {
  method: 'POST',
  body: JSON.stringify({ email, password, device: { name: 'smoke', os: 'Windows', appVersion: '1.1.1' } }),
});
const token = reg.body?.accessToken;
check('register throwaway account', reg.status === 201 && typeof token === 'string', { status: reg.status, code: reg.body?.error?.code });

const bad = await call('/auth/login', {
  method: 'POST',
  body: JSON.stringify({ email, password: 'wrong-password', device: { name: 'smoke' } }),
});
check('login rejects a wrong password', bad.status === 401 && bad.body?.error?.code === 'invalid_credentials', { status: bad.status, code: bad.body?.error?.code });

const good = await call('/auth/login', {
  method: 'POST',
  body: JSON.stringify({ email, password, device: { name: 'smoke', os: 'Windows', appVersion: '1.1.1' } }),
});
const auth = { authorization: `Bearer ${good.body?.accessToken ?? ''}` };
check('login accepts the right password', good.status === 200 && typeof good.body?.accessToken === 'string', { status: good.status });

const me = await call('/account/me', { headers: auth });
check('session reads the account', me.status === 200, { status: me.status, email: me.body?.user?.email ?? me.body?.email });

// ---- signed channel: fail-closed inbox
const unsigned = await call(`${BASE}${INBOX}/events`, { method: 'POST', body: JSON.stringify({ eventId: 'smoke', eventType: 'subscription.activated' }) });
check('inbox rejects unsigned delivery', unsigned.status === 401 && unsigned.body?.error === 'missing_signature_headers', { status: unsigned.status, error: unsigned.body?.error });

const wrongSecret = crypto.randomBytes(32).toString('hex');
const bodyText = JSON.stringify({ eventId: `smoke-${Date.now()}`, eventType: 'subscription.activated', version: 1, payload: {} });
const ts = String(Date.now());
const nonce = crypto.randomBytes(16).toString('hex');
const canonical = ['v1', ts, nonce, 'POST', `${INBOX}/events`, crypto.createHash('sha256').update(bodyText, 'utf8').digest('hex')].join('\n');
const sig = crypto.createHmac('sha256', wrongSecret).update(canonical, 'utf8').digest('hex');
const forged = await fetch(`${BASE}${INBOX}/events`, {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'x-np-timestamp': ts, 'x-np-nonce': nonce, 'x-np-request-id': crypto.randomUUID(), 'x-np-signature': sig },
  body: bodyText,
  signal: AbortSignal.timeout(25_000),
});
const forgedBody = await forged.json().catch(() => null);
check('inbox rejects a forged signature', forged.status === 401 && forgedBody?.error === 'invalid_signature', { status: forged.status, error: forgedBody?.error });

// ---- signed channel: worker -> production bot (outbound signatures accepted?)
const start = await call('/account/telegram/link', { method: 'POST', headers: auth, body: '{}' });
const code = start.body?.token;
const deepLink = start.body?.deepLink;
check('signed link/request is accepted by the production bot', start.status === 200 && typeof code === 'string' && typeof deepLink === 'string', {
  status: start.status,
  code: start.body?.error?.code ?? start.body?.error,
  deepLink: typeof deepLink === 'string' ? deepLink.replace(/([?&]start=).*/, '$1…') : null,
});

if (typeof code === 'string') {
  const confirm = await call('/account/telegram/link/confirm', { method: 'POST', headers: auth, body: JSON.stringify({ code }) });
  // No Telegram identity is bound to this fresh code, so the bot must refuse the
  // CLAIM with its own business error (400 invalid_or_expired) — a 502/503 here
  // would mean the signed claim never reached the bot.
  check('signed link/claim reaches the bot (business refusal, not a transport failure)', confirm.status === 400, {
    status: confirm.status,
    code: confirm.body?.error?.code,
  });
}

const link = await call('/account/telegram', { headers: auth });
check('telegram status stays unlinked', link.status === 200 && link.body?.connected === false, { status: link.status, connected: link.body?.connected });

const subs = await call('/subscriptions', { headers: auth });
check('subscriptions list answers', subs.status === 200 && Array.isArray(subs.body?.subscriptions), { status: subs.status, count: subs.body?.subscriptions?.length });

const failed = results.filter((r) => !r.ok);
console.log(`\n${results.length - failed.length}/${results.length} passed, ${failed.length} failed`);
console.log(`EMAIL=${email}`);
process.exit(failed.length === 0 ? 0 : 1);
