{"kind":"tool","id":"b2uznzqqLrc","toolName":"write_file","input":{"path":"tmp/signed-channel-accepted-smoke.mjs","instructions":"Write a throwaway local-only smoke that exercises the accepted-event path, replay refusal, and eventId idempotency.","content":"/**
 * Accepted-event + replay smoke for the signed inbox (LOCAL runtime only).
 * Sends a real `subscription.activated` event for an unlinked account so the
 * worker takes the full ingest path (parked `no_link`) without touching any
 * entitlement, then proves replay refusal and eventId idempotency.
 */
import { createHash, createHmac, randomBytes, randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';

const BASE = 'http://127.0.0.1:8792';
const PATH = '/api/internal/netpulse/v1/events';
const secret = readFileSync('/tmp/np-smoke-secret.txt', 'utf8').trim();

const sha256Hex = (s) => createHash('sha256').update(s, 'utf8').digest('hex');
const hmacHex = (k, m) => createHmac('sha256', k).update(m, 'utf8').digest('hex');
const canon = (ts, nonce, method, path, bh) => ['v1', ts, nonce, method, PATH ? 'POST' : '', path, bh].join('\n');

function request(bodyText, nonce = randomBytes(16).toString('hex')) {
  const ts = String(Date.now());
  const sig = hmacHex(secret, ['v1', ts, nonce, 'POST', PATH, sha256Hex(bodyText)].join('\n'));
  return {
    headers: {
      'Content-Type': 'application/json',
      'x-np-timestamp': ts,
      'x-np-nonce': nonce,
      'x-np-request-id': randomUUID(),
      'x-np-signature': sig,
    },
    bodyText,
  };
}

async function post(req) {
  const res = await fetch(`${BASE}${PATH}`, { method: 'POST', headers: req.headers, body: req.bodyText });
  return { status: res.status, body: await res.json().catch(() => null) };
}

const eventId = `smoke-${randomBytes(8).toString('hex')}`;
const accountId = `npa_smoke_${randomBytes(6).toString('hex')}`;
const bodyText = JSON.stringify({
  eventId,
  eventType: 'subscription.activated',
  version: 1,
  netpulseAccountId: accountId,
  payload: { subscription: { subscriptionId: 9001, planCode: 'pro', status: 'active', startedAt: '2026-10-01 00:00:00', expiresAt: '2026-11-01 00:00:00', autoRenew: false, totalGb: 50, usedGb: 0, ipLimit: 2 } },
