export function buildXrayMultiConfig(
  nodes: readonly MultiCoreNode[],
  ports: readonly number[],
): Record<string, unknown> {
  assertBatchShape(nodes, ports);
  const inbounds = nodes.map((_, i) => ({
    tag: multiInboundTag(i),
    listen: '127.0.0.1',
    port: ports[i],
    protocol: 'http',
