  const rules = nodes.map((_, i) => ({
    type: 'field',
    inboundTag: [multiInboundTag(i)],
    outboundTag: multiOutboundTag(i),
  }));
  return {
    log: { loglevel: 'warning' },
    inbounds,
    outbounds,
    routing: { domainStrategy: 'AsIs', rules },
  };
}

